Object.assign(window.I18N,{"Wer hat dich am meisten angegriffen?": "Хто атакував тебе найбільше?", "niemand besonders": "ніхто особливо", "konnte von einem Angriff auf {0} nicht ablassen, obwohl er dort deutlich mehr verlor als gewann": "не зміг відмовитися від атаки на {0}, хоча втрачав там значно більше, ніж здобував", "Sunk-Cost-Effekt": "ефект невідшкодовних витрат", "Verlustaversion": "неприйняття втрат", "Vergeltungsimpuls": "імпульс відплати", "Impulsives Schnelldenken": "імпульсивне швидке мислення", "Feindseligkeitsverzerrung": "ворожа атрибутивна помилка", "Introspektionsillusion": "ілюзія інтроспекції", "Selbstwertdienliche Verzerrung": "корислива помилка атрибуції", "Kognitive Verzerrung – Erklärung öffnen": "Когнітивне упередження – відкрити пояснення", "Psychologie": "Психологія"});
